import {countryOptions,syncRegionFields,chooseRegion,mergePlaceLabels} from './geography.js';
import {preparePhotoBatch,proposePhotoGroups,applyPhotoBatch,groupBatchAtLocation,batchCoordinates} from './batch-import.js';
import {parseTags} from './journal-tools.js';
import {placeView} from './visits.js';
import {proximityKm} from './nearby-memories.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createBatchImportUI({document,getState,write,read,createStage,today,lookupRegion,onSaved,onStatus=()=>{},confirm=globalThis.confirm}){
 const $=id=>document.getElementById(id);let groups=[],duplicates=0,phase='idle',abort=null,generation=0,undoGroups=null,sources=[],grouping='place',reviewEdited=false,reviewStage=null;
 const groupingHelp={place:'Same photo date and nearby location: automatic groups need an embedded photo date and GPS within 100 m of the first photo. Missing either stays separate.',same:'Same photo date and same location: automatic groups need an embedded photo date and GPS matching to five decimal places (about 1 m). Missing either stays separate.',individual:'One visit per photo: review each photo separately, then save as a new footprint or a return visit.',together:'All selected photos in one footprint: combine up to 30 unique photos, even without GPS or with different dates. Review one shared name, date, location and story. The first detected photo date and GPS are proposed; originals stay unchanged.'};
 function modeHelp(){$('batch-grouping-help').textContent=groupingHelp[$('batch-grouping').value]??'';}
 function targets(g){let records=getState().records.filter(r=>!g.targetQuery||r.title.toLocaleLowerCase().includes(g.targetQuery.toLocaleLowerCase()));if(Number.isFinite(g.lat))records=records.slice().sort((a,b)=>{const x=placeView(a),y=placeView(b);return (Number.isFinite(x.lat)?proximityKm(g,x):Infinity)-(Number.isFinite(y.lat)?proximityKm(g,y):Infinity)||a.title.localeCompare(b.title);});else records=records.slice().sort((a,b)=>a.title.localeCompare(b.title));const chosen=getState().records.find(r=>r.id===g.targetId);records=records.slice(0,30);if(chosen&&!records.some(r=>r.id===chosen.id))records.unshift(chosen);return '<option value="">New footprint</option>'+records.map(r=>`<option value="${esc(r.id)}" ${r.id===g.targetId?'selected':''}>Return to ${esc(r.title)}</option>`).join('');}
 function references(){const select=$('batch-location-reference'),previous=select.value;select.innerHTML='<option value="">Choose reviewed coordinates</option>'+groups.filter(g=>g.selected&&Number.isFinite(g.lat)&&Number.isFinite(g.lng)).map(g=>`<option value="${esc(g.id)}">${esc(g.title)} · ${esc(g.visited)} · ${batchCoordinates(g)}</option>`).join('');if([...select.options].some(o=>o.value===previous))select.value=previous;}
 function groupRow(g){return $('batch-groups').querySelector(`[data-group="${groups.indexOf(g)}"]`);}
 function syncLabels(row,g){if(!row)return;const country=row.querySelector('[data-field="country"]'),region=row.querySelector('[data-field="region"]'),choice=row.querySelector('[data-field="regionChoice"]');country.innerHTML=countryOptions(g.country);country.value=g.country;region.value=g.region;syncRegionFields(country,region,choice);row.querySelector('[data-region-status]').textContent=g.lookupStatus??'';}
 function fillLabels(g,{force=false}={}){const pointKey=`${g.lat},${g.lng}`,automatic=g.autoLabels&&g.country===g.autoLabels.country&&g.region===g.autoLabels.region;if(!lookupRegion||g.selected===false||g.lookupPending||g.country&&g.region&&!automatic||!Number.isFinite(g.lat)||!Number.isFinite(g.lng)||!force&&g.lastLookupPoint===pointKey)return;const base=automatic?{country:'',region:''}:{country:g.country,region:g.region};g.lastLookupPoint=pointKey;const token=generation,version=g.labelVersion??0,point={lat:g.lat,lng:g.lng},current=()=>token===generation&&phase==='idle'&&g.selected!==false&&groups.includes(g)&&(g.labelVersion??0)===version&&g.lat===point.lat&&g.lng===point.lng;g.lookupPending=true;g.lookupStatus='Finding country and state/province…';const row=groupRow(g);if(row)row.querySelector('[data-region-status]').textContent=g.lookupStatus;
  void lookupRegion(point,{isCurrent:current}).then(labels=>{if(!current())return;const next=mergePlaceLabels(base,labels);Object.assign(g,next);g.autoLabels=!base.country&&!base.region?{...next}:null;g.lookupStatus='Country/state lookup finished. Review these labels; existing entries are kept.';syncLabels(groupRow(g),g);}).catch(error=>{if(current()){g.lookupStatus=error.message;const row=groupRow(g);if(row)row.querySelector('[data-region-status]').textContent=g.lookupStatus;}}).finally(()=>{g.lookupPending=false;if(groups.includes(g)&&g.lookupStatus==='Finding country and state/province…'&&!current()){g.lookupStatus='Lookup stopped. Choose labels manually or retry.';const row=groupRow(g);if(row)row.querySelector('[data-region-status]').textContent=g.lookupStatus;}});
 }
 function render(){
  const busy=phase==='reading'||phase==='saving',single=groups.length===1&&groups[0].singleFootprint;modeHelp();$('batch-shared').hidden=!!single;$('batch-save').textContent=single?'Save one footprint':'Save reviewed visits';$('batch-save-help').textContent=single?'All photos above will be saved together as one new footprint, using the shared fields you review here. Original photo dates and GPS stay unchanged.':'Each checked group becomes a new footprint or a return visit at the selected place. Labels and tags can be added to existing places; their saved stories and media stay. Nothing is saved until you confirm.';$('batch-pick').inert=busy;$('batch-review').inert=busy;$('batch-cancel-work').hidden=!busy;$('batch-cancel-work').disabled=phase==='saving'||!!abort?.signal.aborted;$('batch-review').hidden=!groups.length;$('batch-summary').textContent=single?`${groups[0].photos.length} photos → 1 footprint · ${duplicates} duplicate photos skipped. Review the shared fields below.`:groups.length?`${groups.length} proposed visits · ${duplicates} duplicate photos skipped. Review dates, locations and targets before saving.`:'';
  if(busy)return;references();$('batch-undo-grouping').hidden=!undoGroups;
  const journeys=getState().journeys.filter(j=>!j.deleted);$('batch-groups').innerHTML=groups.map((g,i)=>`<article class="batch-group" data-group="${i}"><div class="batch-group-heading"><img src="${esc(g.photos[0])}" alt="Preview of imported photo group" loading="lazy" decoding="async"><div>${g.singleFootprint?`<p class="batch-one-label"><strong>1 footprint · ${g.photos.length} photos</strong></p>`:`<label class="checkbox"><input type="checkbox" data-field="selected" ${g.selected?'checked':''}>Keep this visit · ${g.photos.length} photos</label>`}<p class="field-help">${esc(g.dateSource)} · ${esc(g.locationSource?g.locationSource+(Number.isFinite(g.lat)?': '+batchCoordinates(g):''):(g.lat===null?'No photo GPS — location is optional':'Group coordinates: '+batchCoordinates(g)))}</p><details><summary>Photo names, dates &amp; GPS</summary><p class="field-help">${g.files.map((name,index)=>`${esc(name)} · ${esc(g.photoMetadata?.[index]?.takenOn??'No photo date')} · ${esc(batchCoordinates(g.photoMetadata?.[index]?.location))}`).join('<br>')}</p></details></div></div>${g.singleFootprint?`<div class="batch-photos" aria-label="Photos included in this footprint">${g.photos.map((src,index)=>`<img src="${esc(src)}" alt="${esc(g.files[index])}" loading="lazy">`).join('')}</div>`:`<div class="field"><label>Find a saved place<input type="search" data-field="targetQuery" value="${esc(g.targetQuery??'')}" placeholder="Search, or leave as a new footprint"></label></div><div class="field"><label>Save as<select data-field="targetId">${targets(g)}</select></label></div>`}<div class="two-fields"><div class="field"><label>Place name<input data-field="title" maxlength="160" value="${esc(g.title)}" ${g.targetId?'disabled':''}></label></div><div class="field"><label>Date visited<input data-field="visited" type="date" value="${esc(g.visited)}"></label></div></div><div class="two-fields"><div class="field"><label>Category<select data-field="category" ${g.targetId?'disabled':''}>${['Food & Drink','Things to do','Shopping','Services','Other'].map(c=>`<option ${c===g.category?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="field"><label>Journey<select data-field="tripId"><option value="">No journey</option>${journeys.map(j=>`<option value="${esc(j.id)}" ${j.id===g.tripId?'selected':''}>${esc(j.title)}</option>`).join('')}</select></label></div></div><div class="two-fields"><div class="field"><label>Latitude<input type="number" step="any" min="-90" max="90" data-field="lat" value="${g.lat??''}"></label></div><div class="field"><label>Longitude<input type="number" step="any" min="-180" max="180" data-field="lng" value="${g.lng??''}"></label></div></div><div class="two-fields"><div class="field"><label>Country<select data-field="country">${countryOptions(g.country)}</select></label></div><div class="field"><label>State / province<select data-field="regionChoice" aria-label="Choose a state or province" hidden></select><input data-field="region" maxlength="100" value="${esc(g.region)}" placeholder="Enter a state / province"></label></div></div><p class="field-help" data-region-status role="status">${esc(g.lookupStatus??'')}</p><button type="button" class="text-button" data-region-lookup="${i}">Fill country/state from coordinates</button><div class="field"><label>Tags to add, separated by commas<input data-field="tags" maxlength="2000" value="${esc(g.tags.join(', '))}"></label></div><div class="field"><label>The story<textarea data-field="notes" maxlength="20000" rows="2">${esc(g.notes)}</textarea></label></div></article>`).join('');for(const g of groups){syncLabels(groupRow(g),g);fillLabels(g);}
 }
 const size=bytes=>bytes>=1024**3?`${(bytes/1024**3).toFixed(2)} GB`:`${(bytes/1024**2).toFixed(1)} MB`;
 function beginProgress(title){$('batch-import').classList.add('batch-transfer-active');$('batch-transfer').hidden=false;$('batch-transfer').dataset.state='working';$('batch-transfer').setAttribute('aria-busy','true');$('batch-transfer-title').textContent=title;$('batch-percent').textContent='0%';$('batch-progress').value=0;$('batch-file').textContent='';$('batch-progress-detail').textContent='';$('batch-dismiss-progress').hidden=true;$('batch-transfer').scrollIntoView?.({block:'nearest'});}
 function finishProgress(message,{error=false,cancelled=false}={}){$('batch-transfer').setAttribute('aria-busy','false');$('batch-transfer').dataset.state=cancelled?'cancelled':error?'error':'success';$('batch-transfer-title').textContent=cancelled?'Import cancelled':error?'Import could not finish':'Photos ready to review';$('batch-progress-label').textContent=message;$('batch-progress-detail').textContent='Your saved journal has not changed.';$('batch-dismiss-progress').hidden=false;$('batch-dismiss-progress').textContent=error||cancelled?'Back to photos':'Review photos';}
 async function pick(files){
  if(!files.length||phase!=='idle')return;if(groups.length&&!confirm('Replace this unsaved batch review?'))return;
  abort=new AbortController();const token=++generation,wanted=$('batch-grouping').value;let candidate=null;
  phase='reading';beginProgress('Import photo memories');$('batch-progress-label').textContent='Preparing photos on this device…';render();
  try{
   candidate=createStage?.();const result=await preparePhotoBatch(files,{records:getState().records,read:candidate?file=>candidate.read(file):read,today,signal:abort.signal,grouping:wanted,onProgress:(done,total,info)=>{
    if(token!==generation)return;const percent=info.totalBytes?info.bytes/info.totalBytes*100:done/total*100;$('batch-progress').value=percent;$('batch-percent').textContent=`${Math.floor(percent)}%`;$('batch-file').textContent=info.file;$('batch-progress-label').textContent=`${done} of ${total} photos prepared`;$('batch-progress-detail').textContent=`${size(info.bytes)} of ${size(info.totalBytes)} · Reading dates/GPS and preparing originals locally`;
   }});
   if(token!==generation)return;
   const previous=reviewStage;reviewStage=candidate;candidate=null;void previous?.release().catch(()=>{});
   groups=result.groups;sources=result.sources;grouping=wanted;reviewEdited=false;undoGroups=null;duplicates=result.duplicates;
   const message=groups.length?`${sources.length} photos ready · ${duplicates} duplicates skipped. Review before saving.`:'All selected photos are already saved, or repeated in this batch.';$('batch-status').textContent=message;finishProgress(message);if(!groups.length){$('batch-transfer-title').textContent='Photos already saved';$('batch-dismiss-progress').textContent='Choose more photos';}
  }catch(error){if(token===generation){const cancelled=error.message==='CANCELLED',message=cancelled?'Photo import cancelled.':error.name==='QuotaExceededError'?'Not enough device storage for these photos. Free some space or choose a smaller batch.':error.message;$('batch-status').textContent=message;finishProgress(message,{error:!cancelled,cancelled});}}
  finally{try{await candidate?.release();}catch{if(token===generation)$('batch-progress-detail').textContent='Unused photo cleanup will be retried when the journal is next saved.';}if(token===generation){phase='idle';abort=null;$('batch-files').value='';render();}}
 }
 function cancelReading(){if(phase!=='reading')return;abort?.abort();$('batch-cancel-work').disabled=true;$('batch-progress-label').textContent='Cancelling safely…';}
 function releaseReview(){const previous=reviewStage;reviewStage=null;void previous?.release().catch(()=>{});}

 function wire(){
  $('batch-grouping').onchange=()=>{const wanted=$('batch-grouping').value;if(phase!=='idle'){$('batch-grouping').value=grouping;return;}if(wanted===grouping)return;if(sources.length){if(reviewEdited&&!confirm('Rebuild the review with this grouping? Changes to names, dates, locations and other review fields will be reset. Original photos stay.')){$('batch-grouping').value=grouping;modeHelp();return;}try{const next=proposePhotoGroups(sources,{grouping:wanted,today});groups=next;undoGroups=null;reviewEdited=false;}catch(error){$('batch-grouping').value=grouping;modeHelp();$('batch-status').textContent=error.message;return;}}grouping=wanted;modeHelp();render();if(groups.length)$('batch-status').textContent='Grouping updated using the selected photos. Review below; nothing has been saved.';};modeHelp();

  $('batch-same-location').onchange=e=>{$('batch-shared-options').hidden=!e.target.checked;e.target.setAttribute('aria-expanded',String(e.target.checked));references();};
  $('batch-group-shared').onclick=()=>{if(phase!=='idle')return;try{const next=groupBatchAtLocation(groups,$('batch-location-reference').value);if(!confirm('Group checked visits at the chosen coordinates? Reviewed dates stay separate. Names follow the reference/first visit, stories and tags are combined. Original photo GPS stays unchanged.'))return;undoGroups=structuredClone(groups);groups=next;reviewEdited=true;render();$('batch-status').textContent='Grouped at your chosen location. Review below before saving; Undo restores the previous review.';}catch(error){$('batch-status').textContent=error.message;}};
  $('batch-undo-grouping').onclick=()=>{if(phase!=='idle'||!undoGroups)return;if(!confirm('Restore the review before grouping? Any edits since grouping will be discarded.'))return;groups=undoGroups;undoGroups=null;reviewEdited=true;render();$('batch-status').textContent='Previous review restored. Nothing saved.';};
  $('batch-groups').addEventListener('click',e=>{const button=e.target.closest('[data-region-lookup]');if(!button||phase!=='idle')return;const g=groups[Number(button.dataset.regionLookup)];if(!Number.isFinite(g?.lat)||!Number.isFinite(g?.lng)){$('batch-status').textContent='Enter shared coordinates or choose photo GPS first.';return;}fillLabels(g,{force:true});});
  $('batch-files').onchange=e=>void pick([...e.target.files]);$('batch-cancel-work').onclick=cancelReading;$('batch-dismiss-progress').onclick=()=>{$('batch-transfer').hidden=true;$('batch-import').classList.remove('batch-transfer-active');if(groups.length)$('batch-review').scrollIntoView?.({block:'start'});};
  const update=e=>{const row=e.target.closest('[data-group]'),field=e.target.dataset.field;if(!row||!field||phase!=='idle')return;const g=groups[Number(row.dataset.group)];if(!g)return;reviewEdited=true;if(['country','region','regionChoice','lat','lng','targetId'].includes(field)){g.labelVersion=(g.labelVersion??0)+1;g.lookupStatus='Labels / coordinates changed manually.';row.querySelector('[data-region-status]').textContent=g.lookupStatus;}
   if(['country','region','regionChoice'].includes(field))g.autoLabels=null;
   if(field==='country'){g.country=e.target.value;g.region='';syncLabels(row,g);return;}if(field==='regionChoice'){const country=row.querySelector('[data-field=country]'),region=row.querySelector('[data-field=region]');chooseRegion(country,region,e.target);g.region=region.value;return;}
   if(field==='selected')g.selected=e.target.checked;else if(['lat','lng'].includes(field))g[field]=e.target.value===''?null:Number(e.target.value);else if(field==='tags'){try{g.tags=parseTags(e.target.value);g.tagsError='';}catch(error){g.tagsError=error.message;}}else g[field]=e.target.value;
   if(['selected','lat','lng','visited','title'].includes(field))references();
   if(field==='targetQuery')row.querySelector('[data-field="targetId"]').innerHTML=targets(g);
   if(field==='targetId'){const old=getState().records.find(r=>r.id===g.targetId);for(const name of ['title','category']){row.querySelector(`[data-field="${name}"]`).disabled=!!old;if(old){g[name]=old[name];row.querySelector(`[data-field="${name}"]`).value=old[name];}}for(const name of ['country','region'])if(old&&!g[name]){g[name]=old[name]??'';row.querySelector(`[data-field="${name}"]`).value=g[name];}syncLabels(row,g);}
  };$('batch-groups').addEventListener('input',update);$('batch-groups').addEventListener('change',update);
  $('batch-review').onsubmit=async e=>{e.preventDefault();if(phase!=='idle')return;phase='saving';beginProgress('Save photo memories');$('batch-progress').removeAttribute('value');$('batch-percent').textContent='';$('batch-progress-label').textContent='Saving your reviewed visits…';$('batch-progress-detail').textContent='Finishing one save. Keep the app open until it completes.';$('batch-status').textContent='Saving your reviewed batch…';render();try{if(groups.some(g=>g.selected&&g.tagsError))throw Error(groups.find(g=>g.selected&&g.tagsError).tagsError);let result;await write(rows=>{result=applyPhotoBatch(rows,groups,{journeys:getState().journeys});return result.records;});releaseReview();groups=[];sources=[];reviewEdited=false;$('batch-status').textContent=`Saved ${result.added} new places and ${result.returns} return visits.`;phase='idle';render();onSaved(result);}catch(error){$('batch-status').textContent=error.message;finishProgress(error.message,{error:true});}finally{phase='idle';render();}};
 }
 return {wire,hasPending:()=>phase!=='idle'||groups.length>0,open(){releaseReview();$('batch-transfer').hidden=true;$('batch-import').classList.remove('batch-transfer-active');const token=generation;void globalThis.navigator?.storage?.estimate?.().then(estimate=>{if(token===generation)$('batch-storage').textContent=`Estimated storage allowance remaining: ${size(Math.max(0,estimate.quota-estimate.usage))}. Actual free space may be lower.`;}).catch(()=>{});groups=[];sources=[];reviewEdited=false;grouping=$('batch-grouping').value;undoGroups=null;duplicates=0;phase='idle';$('batch-same-location').checked=false;$('batch-same-location').setAttribute('aria-expanded','false');$('batch-shared-options').hidden=true;$('batch-status').textContent='Photos stay on this device. Saved photo dates and GPS are proposed for your review; missing dates start as today.';render();},canClose(){if(phase==='saving'){onStatus('Saving the batch. Please wait.');return false;}if(phase==='reading'){cancelReading();onStatus('Cancelling photo reading. Please wait.');return false;}return !groups.length||confirm('Discard this unsaved photo batch?');},reset(){generation++;releaseReview();abort?.abort();abort=null;groups=[];sources=[];reviewEdited=false;undoGroups=null;phase='idle';$('batch-files').value='';},refresh(){}};
}
